const gold = new THREE.MeshStandardMaterial({ color: 0xf59e0b, metalness: 0.6, roughness: 0.3 });
const ring = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.12, 16, 48), gold);
const shaft = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.18, 0.18), gold);
shaft.position.x = 1.2;
const key = new THREE.Group();
key.add(ring, shaft);
key.position.y = 1.2;
scene.add(key);

const lock = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.1, 0.6), new THREE.MeshStandardMaterial({ color: 0x334155 }));
lock.position.y = -0.6;
scene.add(lock);

scene.add(new THREE.HemisphereLight(0xffffff, 0x334155, 1.4));
const sun = new THREE.DirectionalLight(0xffffff, 1.5);
sun.position.set(3, 5, 4);
scene.add(sun);

const tag = label('Same key, both ways');
tag.position.set(0, 2.3, 0);
scene.add(tag);

onFrame((delta) => {
  key.rotation.y += delta * 0.8;
});
